-- hejmo:foreign-keys-off
-- Birthdays calendar (ticket 302): a calendar generated by the box from the
-- birthdays of the contacts, kind 'birthdays'. SQLite cannot change a CHECK
-- constraint, so the table is rebuilt (the marker above runs this migration
-- with foreign keys off, so the drop does not cascade into events).
CREATE TABLE calendars_new (
    id            TEXT PRIMARY KEY,
    household_id  TEXT NOT NULL REFERENCES households(id) ON DELETE CASCADE,
    name          TEXT NOT NULL,
    kind          TEXT NOT NULL CHECK (kind IN ('local', 'ics', 'caldav', 'google', 'meals', 'outlook', 'birthdays')),
    color         TEXT NOT NULL DEFAULT '',
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    connection_id TEXT REFERENCES calendar_connections(id) ON DELETE CASCADE,
    read_only     INTEGER NOT NULL DEFAULT 0,
    shared        INTEGER NOT NULL DEFAULT 0,
    remote_url    TEXT,
    waste         INTEGER NOT NULL DEFAULT 0,
    source_locked INTEGER NOT NULL DEFAULT 0,
    source_owner  TEXT NOT NULL DEFAULT '',
    source_name   TEXT NOT NULL DEFAULT ''
);
INSERT INTO calendars_new (rowid, id, household_id, name, kind, color, created_at, updated_at, connection_id, read_only, shared, remote_url, waste, source_locked, source_owner, source_name)
    SELECT rowid, id, household_id, name, kind, color, created_at, updated_at, connection_id, read_only, shared, remote_url, waste, source_locked, source_owner, source_name FROM calendars;
DROP TABLE calendars;
ALTER TABLE calendars_new RENAME TO calendars;
CREATE UNIQUE INDEX calendars_remote_url ON calendars (connection_id, remote_url) WHERE remote_url IS NOT NULL;

-- A contact's birthday is in the calendar unless a parent switched it off.
ALTER TABLE contacts ADD COLUMN hide_birthday INTEGER NOT NULL DEFAULT 0;

-- Households with contacts that have a birthday already get the calendar. The
-- events (one yearly series per contact, internal/birthday) are written by the
-- box at its start (store.Open): their ids are UUIDv5 of the contact id, which
-- SQL cannot make. The name is the English one: the box renames nothing.
INSERT INTO calendars (id, household_id, name, kind, color, read_only, shared, created_at, updated_at)
SELECT lower(hex(randomblob(16))), h.id, 'Birthdays', 'birthdays', '#A0526A', 1, 1, h.created_at, h.created_at
FROM households h
WHERE EXISTS (SELECT 1 FROM contacts c WHERE c.household_id = h.id AND c.bday_day IS NOT NULL);
